sys_transform_script.script:
(function runTransformScript(source, map, log, target /*GlideRecord*/) {
	var operation = source.getValue('operation');

	if (operation === 'create_work_note') {
		handleCreateWorkNote();
	} else if (operation === 'update_work_note') {
		handleUpdateWorkNote();
	} else {
		setError('Unknown operation: ' + operation);
	}

	ignore = true; // All writes are handled manually; skip default field mapping

	function handleCreateWorkNote() {
		var incidentSysId = source.getValue('incident_sys_id');
		var workNote = source.getValue('work_note');

		var incidentGR = new GlideRecordSecure('incident');
		if (!incidentGR.get(incidentSysId)) {
			setError('Incident not found with sys_id: ' + incidentSysId);
			return;
		}

		// Idempotency: if this exact work note already exists on the incident,
		// return it instead of adding a duplicate (guards retries/replays).
		var existingGR = new GlideRecordSecure('sys_journal_field');
		existingGR.addQuery('element_id', incidentSysId);
		existingGR.addQuery('element', 'work_notes');
		existingGR.addQuery('value', workNote);
		existingGR.setLimit(1);
		existingGR.query();
		if (existingGR.next()) {
			source.setValue('result_sys_id', existingGR.getUniqueValue());
			source.setValue('result_status', 'success');
			source.setValue('result_message', 'Work note already exists on this incident');
			source.update();
			return;
		}

		incidentGR.work_notes = workNote;
		incidentGR.update();

		var journalGR = new GlideRecordSecure('sys_journal_field');
		journalGR.addQuery('element_id', incidentSysId);
		journalGR.addQuery('element', 'work_notes');
		journalGR.addQuery('value', workNote);
		journalGR.orderByDesc('sys_created_on');
		journalGR.setLimit(1);
		journalGR.query();

		var noteSysId = '';
		if (journalGR.next()) {
			noteSysId = journalGR.getUniqueValue();
		}

		source.setValue('result_sys_id', noteSysId);
		source.setValue('result_status', 'success');
		source.setValue('result_message', 'Work note added successfully');
		source.update();
	}

	function handleUpdateWorkNote() {
		var incidentSysId = source.getValue('incident_sys_id');
		var newWorkNote = source.getValue('work_note');

		var incidentGR = new GlideRecordSecure('incident');
		if (!incidentGR.get(incidentSysId)) {
			setError('Incident not found with sys_id: ' + incidentSysId);
			return;
		}

		// Idempotency: if this exact content already exists on the incident,
		// return it instead of re-posting (guards retries/replays).
		var existingGR = new GlideRecordSecure('sys_journal_field');
		existingGR.addQuery('element_id', incidentSysId);
		existingGR.addQuery('element', 'work_notes');
		existingGR.addQuery('value', newWorkNote);
		existingGR.setLimit(1);
		existingGR.query();
		if (existingGR.next()) {
			source.setValue('result_sys_id', existingGR.getUniqueValue());
			source.setValue('result_status', 'success');
			source.setValue('result_message', 'Work note already exists on this incident');
			source.update();
			return;
		}

		// ServiceNow journal entries are immutable and scoped apps cannot write
		// sys_journal_field directly, so post the updated content as a new work note.
		incidentGR.work_notes = newWorkNote;
		incidentGR.update();

		var journalGR = new GlideRecordSecure('sys_journal_field');
		journalGR.addQuery('element_id', incidentSysId);
		journalGR.addQuery('element', 'work_notes');
		journalGR.addQuery('value', newWorkNote);
		journalGR.orderByDesc('sys_created_on');
		journalGR.setLimit(1);
		journalGR.query();

		var noteSysId = '';
		if (journalGR.next()) {
			noteSysId = journalGR.getUniqueValue();
		}

		source.setValue('result_sys_id', noteSysId);
		source.setValue('result_status', 'success');
		source.setValue('result_message', 'Work note updated (posted as new note)');
		source.update();
	}

	function setError(msg) {
		source.setValue('result_status', 'error');
		source.setValue('result_message', msg);
		source.update();
		error = true;
		errorMessage = msg;
	}

})(source, map, log, target);
